package com.cenedu.backend.ai.problem.render;
import static org.assertj.core.api.Assertions.*; import com.cenedu.backend.ai.problem.adapter.SafeSvgSanitizer; import com.cenedu.backend.domain.problem.authoring.diagram.*; import com.cenedu.backend.domain.problem.authoring.semantic.evaluation.*; import com.cenedu.backend.domain.problem.authoring.semantic.model.*; import java.util.*; import org.junit.jupiter.api.Test;
class AllDiagramFamiliesDetailedTest { private final DiagramViewport v=new DiagramViewport(640,240,16); private final DiagramStyle s=new DiagramStyle("#000000","#FFFFFF","#FF0000",1,"sans-serif",12); private final ProblemDiagramRenderer r=new ProblemDiagramRenderer(new SafeSvgSanitizer()); @Test void planeRendersSegmentsCirclesArcsAnglesAndMeasurements(){var d=new PlaneGeometryDiagramSpecV1(1,"P",DiagramKind.PLANE_GEOMETRY,v,s,List.of(new PlanePointSpec("A","X","Y","A"),new PlanePointSpec("B","X2","Y2","B")),List.of(new PlaneSegmentSpec("S","A","B",false,false)),List.of(new PlaneAngleSpec("G","A","A","B","ANG","angle")),List.of(),List.of(new PlaneCircleSpec("C","A","R","circle")),List.of(new PlaneArcSpec("AR","A","R","SA","EA","arc")),List.of(new PlaneMeasurementSpec("M","S","L","length")));var svg=r.render(d,new DiagramRenderContext(Map.of("X",new SemanticResolvedValue(SemanticValueType.INTEGER,"1",null),"Y",new SemanticResolvedValue(SemanticValueType.INTEGER,"2",null),"X2",new SemanticResolvedValue(SemanticValueType.INTEGER,"3",null),"Y2",new SemanticResolvedValue(SemanticValueType.INTEGER,"4",null),"R",new SemanticResolvedValue(SemanticValueType.INTEGER,"2",null)))).svg();assertThat(svg).contains("<line").contains("<circle").contains("<path").contains("length");} @Test void coordinateAndTableRenderStructuredElements(){var c=new CoordinateGraphDiagramSpecV1(1,"C",DiagramKind.COORDINATE_GRAPH,v,s,"X0","X1","Y0","Y1","XT","YT",List.of(),List.of(),List.of(),List.of(new CoordinateFunctionSpec("F",CoordinateFunctionKind.DIRECT_PROPORTION,"K","f")));var csvg=r.render(c,new DiagramRenderContext(Map.of("K",new SemanticResolvedValue(SemanticValueType.INTEGER,"2",null)))).svg();assertThat(csvg).contains("<path");var t=new DataTableDiagramSpecV1(1,"T",DiagramKind.DATA_TABLE,v,s,List.of("row"),List.of("col"),List.of(new TableCellSpec(0,0,"V","")),Set.of(new TableCellAddress(0,0)));var tsvg=r.render(t,new DiagramRenderContext(Map.of("V",new SemanticResolvedValue(SemanticValueType.INTEGER,"7",null)))).svg();assertThat(tsvg).contains("row").contains("col").contains("7").contains("#FF0000");} }
